import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong(), m = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int[] p = new int[m], pi = new int[m];
        for (int i = 0; i < m; i++) p[i] = (int) nextLong();
        // prefix function of the pattern
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && p[i] != p[j]) j = pi[j - 1];
            if (p[i] == p[j]) j++;
            pi[i] = j;
        }
        long answer = 0;
        int j = 0;
        for (int i = 0; i + 1 < n; i++) {
            int v = Long.compare(a[i + 1], a[i]);
            while (j > 0 && v != p[j]) j = pi[j - 1];
            if (v == p[j]) j++;
            if (j == m) {
                answer++;
                j = pi[j - 1];
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m := next(), next()
	a := make([]int, n)
	for i := range a {
		a[i] = next()
	}
	p := make([]int, m)
	for i := range p {
		p[i] = next()
	}
	// prefix function of the pattern
	pi := make([]int, m)
	for i := 1; i < m; i++ {
		j := pi[i-1]
		for j > 0 && p[i] != p[j] {
			j = pi[j-1]
		}
		if p[i] == p[j] {
			j++
		}
		pi[i] = j
	}
	answer, j := 0, 0
	for i := 0; i+1 < n; i++ {
		v := 0
		if a[i+1] > a[i] {
			v = 1
		} else if a[i+1] < a[i] {
			v = -1
		}
		for j > 0 && v != p[j] {
			j = pi[j-1]
		}
		if v == p[j] {
			j++
		}
		if j == m {
			answer++
			j = pi[j-1]
		}
	}
	fmt.Println(answer)
}
